import{_ as i,o as a,c as n,ag as l}from"./chunks/framework.PVHj0As1.js";const p="/pub-blog/assets/image-20250105111010688.C87418ZT.png",h="/pub-blog/assets/image-20250105111545129.C33y_LgC.png",t="/pub-blog/assets/image-20250105111747871.XlnhhpoK.png",k="/pub-blog/assets/image-20250105112201927.Cpr4arv1.png",e="/pub-blog/assets/image-20250105145524700.BKrF61TT.png",r="/pub-blog/assets/PixPin_2025-01-05_15-20-57.CfbyRd38.gif",E="/pub-blog/assets/PixPin_2025-01-05_15-36-24.2KvhK4uK.gif",u=JSON.parse('{"title":"鸿蒙元服务实战-笑笑五子棋（4）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（4）/鸿蒙元服务实战-笑笑五子棋（4）.md","filePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（4）/鸿蒙元服务实战-笑笑五子棋（4）.md","lastUpdated":1736065340000,"__rawMarkdown":"# 鸿蒙元服务实战-笑笑五子棋（4）\\n\\n我们在这一章节主要实现五子棋的基本逻辑\\n\\n\\n\\n## 核心目录结构\\n\\n```\\n├─ets\\n│  ├─entryability\\n│  │      EntryAbility.ets\\n│  │      \\n│  ├─entryformability\\n│  │      EntryFormAbility.ets\\n│  │      \\n│  ├─pages\\n│  │      Index.ets\\n│  │      \\n│  ├─views\\n│  │      About.ets\\n│  │      Home.ets\\n│  │      \\n│  └─widget\\n│      └─pages\\n│              WidgetCard.ets\\n│              \\n└─resources\\n    ├─base\\n    │  ├─element\\n    │  │      color.json\\n    │  │      float.json\\n    │  │      string.json\\n    │  │      \\n    │  ├─media\\n    │  │      right.svg\\n    │  │      startIcon.png\\n    │  │      \\n    │  └─profile\\n    │          form_config.json\\n    │          main_pages.json\\n    │          \\n    ├─en_US\\n    │  └─element\\n    │          string.json\\n    │          \\n    ├─rawfile\\n    └─zh_CN\\n        └─element\\n                string.json\\n```\\n\\n\\n\\n## 沉浸式设计\\n\\n![image-20250105111010688](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/image-20250105111010688.png)\\n\\n1. `entry/src/main/ets/entryability/EntryAbility.ets`  中统一设置\\n\\n   ```javascript\\n     onWindowStageCreate(windowStage: window.WindowStage): void {\\n       windowStage.getMainWindow()\\n         .then(windowClass => {\\n           // 设置沉浸式\\n           windowClass.setWindowLayoutFullScreen(true)\\n   \\n           // 顶部状态栏\\n           const topAvoidArea = windowClass.getWindowAvoidArea(window.AvoidAreaType.TYPE_SYSTEM);\\n           const topRectHeight = topAvoidArea.topRect.height;\\n           // px转vp\\n           const vpTopHeight = px2vp(topRectHeight)\\n   \\n           // 底部导航条\\n           const bottomAvoidArea = windowClass.getWindowAvoidArea(window.AvoidAreaType.TYPE_NAVIGATION_INDICATOR);\\n           const bottomRectHeight = bottomAvoidArea.bottomRect.height;\\n           const vpBottomHeight = px2vp(bottomRectHeight)\\n   \\n           AppStorage.setOrCreate(\'topRect\', vpTopHeight)\\n           AppStorage.setOrCreate(\'bottomRect\', vpBottomHeight)\\n         })\\n       windowStage.loadContent(\'pages/Index\', (err) => {\\n         // ...\\n       });\\n     }\\n   ```\\n\\n2. 页面通过padding避开顶部和底部\\n\\n   ```jsx\\n     @StorageProp(\\"topRect\\")\\n     topRect: number = 0\\n     @StorageProp(\\"bottomRect\\")\\n     bottomRect: number = 0\\n     build() {\\n       Column() {\\n   \\t// ...\\n       }\\n       .width(\'100%\')\\n       .height(\'100%\')\\n       .linearGradient({\\n         colors: [[\\"#DEF9ED\\", 0], [\\"#F4F5F7\\", 0.4]]\\n       })\\n       .padding({\\n         top: this.topRect,\\n         bottom: this.bottomRect\\n       })\\n     }\\n   ```\\n\\n   ![image-20250105111545129](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/image-20250105111545129.png)\\n\\n## AtomicServiceTabs\\n\\n[AtomicServiceTabs](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/ohos-atomicservice-atomicservicetabs-V13#atomicservicetabs-1)是元服务独有的tab组件。**Tabs**组件后续不再支持在元服务中进行使用。，对Tabs组件一些不需提供给用户自定义设计的属性进行简化，限制最多显示5个页签，固定页签样式，位置和大小。\\n\\n![image-20250105111747871](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/image-20250105111747871.png)\\n\\n\\n\\n\\n\\n### 基本用法\\n\\n```jsx\\n  AtomicServiceTabs({\\n    // 内容\\n    tabContents: [\\n      () => {\\n          // 自定义构建函数\\n        this.tabContent1()\\n      },\\n      () => {\\n          // 自定义构建函数\\n        this.tabContent2()\\n      }\\n    ],\\n    // 标题\\n    tabBarOptionsArray: [\\n      new TabBarOptions($r(\'sys.media.save_button_picture\'), \'玩吧\', \\"#666\\", \\"#07C160\\"),\\n      new TabBarOptions($r(\'sys.media.AI_keyboard\'), \'关于\', \\"#666\\", \\"#07C160\\"),\\n    ],\\n    // 标题显示的位置\\n    tabBarPosition: TabBarPosition.BOTTOM,\\n    // 背景颜色\\n    barBackgroundColor: 0xffffff,\\n  })\\n```\\n\\n\\n\\n## Home 和 About\\n\\n![image-20250105112201927](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/image-20250105112201927.png)\\n\\nHome表示首页，用来显示主要内容\\n\\nAbout 表示关于，用来存放项目的基本信息\\n\\n他们目前都是普通的组件，分别放在 **tabContent1**  和 tabContent2 内\\n\\n\\n\\n## 引入canvas\\n\\n在Home中开始引入**canvas**\\n\\n```jsx\\n@Component\\nexport struct Home {\\n  settings: RenderingContextSettings = new RenderingContextSettings(true);\\n  ctx: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);\\n\\n  build() {\\n    Column() {\\n      Canvas(this.ctx)\\n        .width(width)\\n        .height(width)\\n        .backgroundColor(Color.Orange)\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 绘制棋盘\\n\\n![image-20250105145524700](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/image-20250105145524700.png)\\n\\n绘制棋盘的思路如下：\\n\\n1. 确定要绘制多少个格子。\\n2. 每一个格子多大\\n\\n---\\n\\n这里的想法比较简单：\\n\\n1. 确定要绘制的格子是 15个。\\n\\n   ```jsx\\n   gridSize: number = 15;\\n   ```\\n\\n   \\n\\n2. 每一个格多大，由屏幕宽度决定。比如屏幕宽度的90%，然后分成15份。每一份就是格子的宽度\\n\\n   ```jsx\\n   // 获取屏幕的宽度的 90%\\n   const width = px2vp(display.getDefaultDisplaySync().availableWidth) * 0.9\\n   // 棋盘是正方形的，所以高度和宽度相等\\n   const height = width\\n   \\n   cellSize: number = width / this.gridSize;\\n   ```\\n\\n\\n\\n3.  然后封装描绘画面的方法 `drawBoard`\\n\\n   ```jsx\\n     // 绘制棋盘\\n     drawBoard = () => {\\n       this.ctx.clearRect(0, 0, width, height);\\n       // 绘制网格\\n       this.ctx.strokeStyle = \\"#000\\";\\n       this.ctx.lineWidth = 1;\\n       for (let i = 0; i < this.gridSize; i++) {\\n         this.ctx.beginPath();\\n         this.ctx.moveTo(this.cellSize * i, 0);\\n         this.ctx.lineTo(this.cellSize * i, height);\\n         this.ctx.stroke();\\n   \\n         this.ctx.beginPath();\\n         this.ctx.moveTo(0, this.cellSize * i);\\n         this.ctx.lineTo(width, this.cellSize * i);\\n         this.ctx.stroke();\\n       }\\n     }\\n   ```\\n\\n4. canvas准备好的时候开始绘制\\n\\n   ```jsx\\n     Canvas(this.ctx)\\n       .width(width)\\n       .height(width)\\n       .backgroundColor(Color.Orange)\\n       .onReady(() => {\\n           this.drawBoard()\\n       })\\n   ```\\n\\n   \\n\\n\\n\\n## 点击下棋\\n\\n点击下棋要是做挺多的处理的，比如：\\n\\n1. 当前是下黑棋还是白棋\\n2. 下完这一子之后，胜利了还是继续下。\\n\\n---\\n\\n我们开始吧：\\n\\n1. 初始化棋盘数据，它是一个二维数组，下棋的时候，其实也是往里面填充内容\\n\\n   ```javascript\\n     // 棋盘数据\\n     board: number[][] = []\\n   ```\\n\\n   \\n\\n2. 初始化当前下棋的角色 设定 1：黑旗 ，2：白旗\\n\\n   ```javascript\\n     currentPlayer: number = 1; // 当前玩家 (1: 黑子, 2: 白子)\\n   ```\\n\\n   \\n\\n3. 声明初始化棋盘的函数，负责初始化棋盘数据和描绘棋盘\\n\\n   ```javascript\\n     initGame = () => {\\n       this.board = []\\n       for (let index = 0; index < this.gridSize; index++) {\\n         const arr: number[] = []\\n         for (let index2 = 0; index2 < this.gridSize; index2++) {\\n           //  0 表示当前没有人在下棋\\n           arr.push(0)\\n         }\\n         this.board.push(arr)\\n       }\\n       // this.currentPlayer = 1;\\n       // this.gameOver = false;\\n       // this.textContent = \'轮到黑子落子\';\\n       this.drawBoard();\\n     }\\n     \\n    -------------------\\n      Canvas(this.ctx)\\n       .width(width)\\n       .height(width)\\n       .backgroundColor(Color.Orange)\\n       .onReady(() => {\\n         this.initGame()\\n       })\\n   ```\\n\\n4. 声明点击棋盘事件，事件中执行下棋逻辑\\n\\n   ```jsx\\n   handleClick = async (event: ClickEvent) => {\\n       const x = event.x;\\n       const y = event.y;\\n   \\n       const col = Math.floor(x / this.cellSize);\\n       const row = Math.floor(y / this.cellSize);\\n   \\n       if (this.board[row] && this.board[row][col] === 0) {\\n         this.board[row][col] = this.currentPlayer;\\n         this.drawBoard();\\n         this.currentPlayer = this.currentPlayer === 1 ? 2 : 1;\\n       } else {\\n         promptAction.showToast({ message: `请点击中棋盘对位位置` })\\n       }\\n     }\\n   ```\\n\\n5. 调整 `drawBoard` 函数，根据 `this.board[row][col] ` 描绘出旗子\\n\\n   ```jsx\\n     // 绘制棋盘\\n     drawBoard = () => {\\n       this.ctx.clearRect(0, 0, width, height);\\n   \\n       // 绘制网格\\n       this.ctx.strokeStyle = \\"#000\\";\\n       this.ctx.lineWidth = 1;\\n       for (let i = 0; i < this.gridSize; i++) {\\n         this.ctx.beginPath();\\n         this.ctx.moveTo(this.cellSize * i, 0);\\n         this.ctx.lineTo(this.cellSize * i, height);\\n         this.ctx.stroke();\\n   \\n         this.ctx.beginPath();\\n         this.ctx.moveTo(0, this.cellSize * i);\\n         this.ctx.lineTo(width, this.cellSize * i);\\n         this.ctx.stroke();\\n       }\\n       // 绘制已落的棋子\\n       for (let row = 0; row < this.gridSize; row++) {\\n         for (let col = 0; col < this.gridSize; col++) {\\n           if (this.board[row][col] !== 0) {\\n             this.ctx.beginPath();\\n             this.ctx.arc(col * this.cellSize + this.cellSize / 2, row * this.cellSize + this.cellSize / 2, this.radius, 0,\\n               2 * Math.PI);\\n             this.ctx.fillStyle = this.board[row][col] === 1 ? \'black\' : \'white\';\\n             this.ctx.fill();\\n             this.ctx.stroke();\\n           }\\n         }\\n       }\\n     }\\n   ```\\n\\n6. 效果\\n\\n   ![PixPin_2025-01-05_15-20-57](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/PixPin_2025-01-05_15-20-57.gif)\\n\\n\\n\\n## 判断输赢\\n\\n五子棋判断输赢的方法比较简单，只需要知道是否有**五子连珠**就行\\n\\n1. 定义判断输赢的方法 `checkWin`\\n\\n   ```jsx\\n       // 判断是否有五子连珠\\n       checkWin = (row: number, col: number) => {\\n         // 定义一个接口abc，用于表示方向相关的偏移量，dr表示行方向的偏移量，dc表示列方向的偏移量\\n         interface abc {\\n           dr: number\\n           dc: number\\n         }\\n     \\n         // 定义一个包含四个方向偏移量信息的数组，分别对应不同的检查方向\\n         const directions: abc[] = [\\n           { dr: 0, dc: 1 }, // 水平方向，行偏移量为0，列偏移量为1，即向右检查\\n           { dr: 1, dc: 0 }, // 垂直方向，行偏移量为1，列偏移量为0，即向下检查\\n           { dr: 1, dc: 1 }, // 主对角线方向，行和列偏移量都为1，向右下方向检查\\n           { dr: 1, dc: -1 }// 副对角线方向，行偏移量为1，列偏移量为 -1，即向右上方向检查\\n         ];\\n     \\n         // 遍历四个不同的方向，依次检查每个方向上是否有五子连珠情况\\n         for (let i = 0; i < directions.length; i++) {\\n           const dr = directions[i].dr;\\n           const dc = directions[i].dc;\\n           let count = 1;\\n     \\n           // 向一个方向检查（从当前落子位置开始，沿着指定方向向前检查）\\n           // 循环尝试查找连续相同颜色的棋子，最多查找连续4个（因为已经有当前落子算1个了，凑够5个判断赢）\\n           for (let i = 1; i < 5; i++) {\\n             let r = row + dr * i;\\n             let c = col + dc * i;\\n             // 判断当前位置是否在棋盘范围内，并且此位置的棋子颜色是否和当前玩家的棋子颜色相同\\n             if (r >= 0 && r < this.gridSize && c >= 0 && c < this.gridSize && this.board[r][c] === this.currentPlayer) {\\n               count++;\\n             } else {\\n               break;\\n             }\\n           }\\n     \\n           // 向另一个方向检查（从当前落子位置开始，沿着指定方向的反方向检查）\\n           // 同样循环尝试查找连续相同颜色的棋子，最多查找连续4个\\n           for (let i = 1; i < 5; i++) {\\n             let r = row - dr * i;\\n             let c = col - dc * i;\\n             if (r >= 0 && r < this.gridSize && c >= 0 && c < this.gridSize && this.board[r][c] === this.currentPlayer) {\\n               count++;\\n             } else {\\n               break;\\n             }\\n           }\\n     \\n           // 如果在当前方向（正方向和反方向结合起来）上连续相同颜色的棋子数量达到或超过5个，则表示当前玩家胜利\\n           if (count >= 5) {\\n             return true;\\n           }\\n         }\\n     \\n         // 如果遍历完所有方向都没有出现五子连珠的情况，则返回false，表示当前落子未形成胜利局面\\n         return false;\\n       }\\n   ```\\n\\n   \\n\\n\\n\\n2. 在点击下棋时 判断是否输赢 `handleClick`\\n\\n   ```jsx\\n       if (this.board[row] && this.board[row][col] === 0) {\\n         this.board[row][col] = this.currentPlayer;\\n         this.drawBoard();\\n   \\n         if (this.checkWin(row, col)) {  // 执行后续逻辑\\n   ```\\n\\n3. 在  `handleClick`中判断输赢后，再做后续的一些小逻辑\\n\\n   1. 如 还没决定输赢，继续下棋\\n   2. 决定输赢了，弹出对话框恭喜胜利者， 询问是否还要再下一盘。。\\n   3. 完整代码\\n\\n   ```jsx\\n     // 处理玩家落子\\n     handleClick = async (event: ClickEvent) => {\\n       if (this.gameOver) {\\n         return;\\n       }\\n   \\n       const x = event.x;\\n       const y = event.y;\\n   \\n       const col = Math.floor(x / this.cellSize);\\n       const row = Math.floor(y / this.cellSize);\\n   \\n       if (this.board[row] && this.board[row][col] === 0) {\\n         this.board[row][col] = this.currentPlayer;\\n         this.drawBoard();\\n   \\n         if (this.checkWin(row, col)) {\\n           this.textContent = this.currentPlayer === 1 ? \'黑子胜利!\' : \'白子胜利!\';\\n           this.gameOver = true;\\n           // AlertDialog.show({ message: this.textContent })\\n           const res = await promptAction.showDialog({\\n             title: this.textContent,\\n             message: \\"重新再来一盘吗\\",\\n             buttons: [\\n               { text: \\"不了\\", color: \\"#000\\" },\\n               { text: \\"来吧\\", color: \\"#0094ff\\" },\\n             ]\\n           })\\n           if (res.index === 1) {\\n             this.initGame()\\n           }\\n   \\n         } else {\\n           this.currentPlayer = this.currentPlayer === 1 ? 2 : 1;\\n           this.textContent = this.currentPlayer === 1 ? \'轮到黑子落子\' : \'轮到白子落子\';\\n         }\\n       } else {\\n         promptAction.showToast({ message: `请点击中棋盘对位位置` })\\n       }\\n     }\\n   ```\\n\\n4. 效果\\n\\n   ![PixPin_2025-01-05_15-36-24](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%884%EF%BC%89.assets/PixPin_2025-01-05_15-36-24.gif)\\n\\n\\n\\n\\n\\n## 总结\\n\\n本章节多了一些业务的具体实现，尤其是下棋的一些逻辑处理上。\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}'),d={name:"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（4）/鸿蒙元服务实战-笑笑五子棋（4）.md"};function g(c,s,y,b,F,o){return a(),n("div",null,[...s[0]||(s[0]=[l("",41)])])}const m=i(d,[["render",g]]);export{u as __pageData,m as default};
